contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (10)); require(amount <= 1000000000000000000000000000000);
        require(amount != 10);
        require(amount < 10);

        bool wrongReverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wrongReverted = true;
        } else {
            wrongReverted = false;
        }

        bool exactReverted;
        c.play{value: 10}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            exactReverted = true;
        } else {
            exactReverted = false;
        }

        assert(wrongReverted && !exactReverted);
    }

    receive() external payable {}
}

